CREATE OR REPLACE FUNCTION public.save_inspection_numbers(_id uuid,_inspection text,_vendor text DEFAULT NULL,_set_vendor boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_admin() OR NOT public.purchase_visible(_id) THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.purchase_admin_fields(purchase_id,inspection_no,vendor_no) VALUES(_id,NULLIF(btrim(_inspection),''),NULLIF(btrim(_vendor),'')) ON CONFLICT(purchase_id) DO UPDATE SET inspection_no=EXCLUDED.inspection_no,vendor_no=CASE WHEN _set_vendor THEN EXCLUDED.vendor_no ELSE public.purchase_admin_fields.vendor_no END,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.save_inspection_numbers(uuid,text,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_inspection_numbers(uuid,text,text,boolean) TO authenticated;